function JumpHint:__init()
    self.controller = nil
    self.JumpUp = nil       -- Action
    self.JumpForward = nil  -- Action
    self.JumpDown = nil     -- Action

    -- 三个 hint 本体
    self.upHint = nil -- RectTransform
    self.forwardHint = nil -- RectTransform
    self.downHint = nil -- RectTransform

    self.upHintEnt = nil -- UI_JumpHintEntity
    self.forwardHintEnt = nil -- UI_JumpHintEntity
    self.downHintEnt = nil -- UI_JumpHintEntity

    self._showUpHint = false
    self._showForwardHint = false
    self._showDownHint = false

    self._upHintWorldPos = Vector3.zero
    self._forwardHintWorldPos = Vector3.zero
    self._downHintWorldPos = Vector3.zero

    self._mainCamera = nil -- Camera
    
    self.rootCanvasCoordinateMatrix = Matrix4x4.identity
    self.currentJumpType = JumpHintType.None

    self.isInit = false
end


function JumpHint:__delete()
    self.co_1 = nil

    if not isNull(self.co_2) then 
        cs_coroutine.stop(self.co_2)
        self.co_2 = nil
    end
end


function JumpHint:Awake()
    KTool.SetActive(self.controller.gameObject, true);
end


function JumpHint:Init( isIgnoreJumpHint_ )

    if isIgnoreJumpHint_ == true then 
        KTool.SetActive( self.upJumpCurveBH, false ) -- 简单隐藏
        return
    end 

    KTool.SetActive(self.controller.gameObject, true)
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    assert(self.jumpHintPrefabInMobile)
    assert(self.jumpHintPrefabInPC)
    assert(self.JumpUp  and self.JumpDown and self.JumpForward )


    assert( self.catHeadTF )

    self.catJumpCurve = DreamSpaceLuaUtils.GetLuaScr(self.upJumpCurveBH.gameObject, "Game.DreamSpace.CharacterController.CatJumpCurve" )
    assert( self.catJumpCurve )
    self.catJumpCurve:Init()


    _ShowJumpHint = function( type, worldPos )
        self:_OnShowJumpHint( type, worldPos )
    end
    
    _HideJumpHint = function(type)
        self:_OnHideJumpHint(type)
    end

    -- must after Awake()
    self._mainCamera = DreamSpaceCamera.GetMainCamera()


    -- ------
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckOrInitSync()
    local parentUICanvas = RoleControllerRootCanvasMgr.dynamicsCanvas
    assert( parentUICanvas )

    -- build ui hint:
    local hintPrefab = nil 
    local uiHintLuaStr = nil
    if DreamSpaceStates.isWindowsPlatform then
        hintPrefab = self.jumpHintPrefabInPC
        uiHintLuaStr = "Game.DreamSpace.Hint.UI_JumpHintEntityInPC"
    else
        hintPrefab = self.jumpHintPrefabInMobile
        uiHintLuaStr = "Game.DreamSpace.Hint.UI_JumpHintEntity"
    end
    --
    self.upHint         = Object.Instantiate(hintPrefab, parentUICanvas.transform) -- RectTransform
    self.forwardHint    = Object.Instantiate(hintPrefab, parentUICanvas.transform) -- RectTransform
    self.downHint       = Object.Instantiate(hintPrefab, parentUICanvas.transform) -- RectTransform
    self.upHint.gameObject.name         = "upHint"
    self.forwardHint.gameObject.name    = "forwardHint"
    self.downHint.gameObject.name       = "downHint"

    -- 一开始就要丢到屏幕外边去:
    self.upHint.transform.position      = idlePosWS
    self.forwardHint.transform.position = idlePosWS
    self.downHint.transform.position    = idlePosWS

    self.upHintEnt      = DreamSpaceLuaUtils.GetLuaScr(self.upHint.gameObject,      uiHintLuaStr ) -- UI_JumpHintEntity / UI_JumpHintEntityInPC
    self.forwardHintEnt = DreamSpaceLuaUtils.GetLuaScr(self.forwardHint.gameObject, uiHintLuaStr ) -- UI_JumpHintEntity / UI_JumpHintEntityInPC
    self.downHintEnt    = DreamSpaceLuaUtils.GetLuaScr(self.downHint.gameObject,    uiHintLuaStr ) -- UI_JumpHintEntity / UI_JumpHintEntityInPC
    assert( self.upHintEnt and self.forwardHintEnt and self.downHintEnt )

    -- 让 hint 也支持按钮交互:
    if DreamSpaceStates.isWindowsPlatform == false then
        self.upHintEnt.button.onClick:AddListener( Bind(self, self._OnJump) )
        self.forwardHintEnt.button.onClick:AddListener( Bind(self, self._OnJump) )
        self.downHintEnt.button.onClick:AddListener( Bind(self, self._OnJump) )
    end

    self.rootCanvasCoordinateMatrix = DreamSpaceUtils.RefreshRootCanvasCoordinateMatrix(self.upHint)

    self.isInit = true
end



function JumpHint:OnDestroy()

    _ShowJumpHint = nil
    _HideJumpHint = nil
    _CurrentChooseJump = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function JumpHint:Update()

    if self.isInit == false then
        return
    end

    self.currentJumpType = JumpHintType.None -- 清空

    local showCount = 0
    if self._showUpHint then
        showCount = showCount + 1
        self.upHint.transform.position = self:_CalculateUIHintPositionWS(self._upHintWorldPos)
        self.currentJumpType = JumpHintType.Up
    else
        self.upHint.transform.position = idlePosWS
    end

    if self._showForwardHint then
        showCount = showCount + 1
        self.forwardHint.transform.position = self:_CalculateUIHintPositionWS(self._forwardHintWorldPos)
        self.currentJumpType = JumpHintType.Forward
    else
        self.forwardHint.transform.position = idlePosWS
    end

    if self._showDownHint then
        showCount = showCount + 1
        self.downHint.transform.position = self:_CalculateUIHintPositionWS(self._downHintWorldPos)
        self.currentJumpType = JumpHintType.Down
    else
        self.downHint.transform.position = idlePosWS
    end

    if showCount > 1 then
        local upDistance = self._showUpHint             and Vector3.SqrMagnitude(self.upHint.localPosition)         or math.huge
        local forwardDistance = self._showForwardHint   and Vector3.SqrMagnitude(self.forwardHint.localPosition)    or math.huge
        local downDistance = self._showDownHint         and Vector3.SqrMagnitude(self.downHint.localPosition)       or math.huge

        self.currentJumpType = self._GetMinimum(upDistance, forwardDistance, downDistance)
    end

    self:_SetAll()

    --assert( not isNull( _CurrentChooseJump ) )
    if isNotNull( _CurrentChooseJump ) then 
        _CurrentChooseJump(self.currentJumpType)
    end 
end


