-- 用户点击 hint ui, 触发跳跃
function JumpHint:_OnJump()
    if self.currentJumpType == JumpHintType.Up then
        self.JumpUp()
    elseif self.currentJumpType == JumpHintType.Forward then
        self.JumpForward()
    elseif self.currentJumpType == JumpHintType.Down then
        self.JumpDown()
    end
end


function JumpHint:_OnShowJumpHint(type, worldPos)
    if self.isInit == false then
        return
    end
    if type == JumpHintType.Up then
        self._showUpHint = true
        self._upHintWorldPos = worldPos
    elseif type == JumpHintType.Forward then
        self._showForwardHint = true
        self._forwardHintWorldPos = worldPos
    elseif type == JumpHintType.Down then
        self._showDownHint = true
        self._downHintWorldPos = worldPos
    end
end





function JumpHint:_OnHideJumpHint(type)
    if self.isInit == false then
        return
    end
    if type == JumpHintType.Up then
        self._showUpHint = false
        self:_SetCanvasGroupParameters(self.upHintEnt, false, 0)
        self._upHintWorldPos = idlePosWS

    elseif type == JumpHintType.Forward then
        self._showForwardHint = false
        self:_SetCanvasGroupParameters(self.forwardHintEnt, false, 0)
        self._forwardHintWorldPos = idlePosWS

    elseif type == JumpHintType.Down then
        self._showDownHint = false
        self:_SetCanvasGroupParameters(self.downHintEnt, false, 0)
        self._forwardHintWorldPos = idlePosWS

    end
end


function JumpHint:_CalculateUIHintPositionWS(worldSpacePos)
    local anchoredPosition = DreamSpaceUtils.CalculateAnchoredPosition(self._mainCamera, worldSpacePos, 0)

    -- 剔除后半球:
    local isDirectionsOpposite = Vector3.Dot(self._mainCamera.transform.forward, worldSpacePos - self._mainCamera.transform.position) < 0

    anchoredPosition = isDirectionsOpposite and outScreenAnchoredPosition or
        InteractableHintUtils.ConstraintAnchoredPositionInScreenBoundaryTrack(anchoredPosition, screenBoundaryTrackRadius)

    return DreamSpaceUtils.AnchoredPosition_To_PosWS(anchoredPosition, self.rootCanvasCoordinateMatrix)
end



function JumpHint._GetMinimum(x1, x2, x3)
    if x1 < x2 then
        return x1 < x3 and JumpHintType.Up or JumpHintType.Down
    else
        return x2 < x3 and JumpHintType.Forward or JumpHintType.Down
    end
end



function JumpHint:_SetAll()
    if self.currentJumpType == JumpHintType.Up then
        --print( "_SetAll - Up" )
        self:_SetCanvasGroup(self.upHintEnt,     self._showUpHint,       true)
        self:_SetCanvasGroup(self.forwardHintEnt, self._showForwardHint, false)
        self:_SetCanvasGroup(self.downHintEnt,   self._showDownHint,     false)

        DreamSpaceStates.IsShowJumpUI = true
        self.catJumpCurve:ShowJump( self.catHeadTF.position, self._upHintWorldPos )

    elseif self.currentJumpType == JumpHintType.Forward then
        --print( "_SetAll - Forward" )
        self:_SetCanvasGroup(self.upHintEnt,     self._showUpHint,       false)
        self:_SetCanvasGroup(self.forwardHintEnt, self._showForwardHint, true)
        self:_SetCanvasGroup(self.downHintEnt,   self._showDownHint,     false)

        DreamSpaceStates.IsShowJumpUI = true
        self.catJumpCurve:ShowJump( self.catHeadTF.position, self._forwardHintWorldPos )


    elseif self.currentJumpType == JumpHintType.Down then
        --print( "_SetAll - Down" )
        self:_SetCanvasGroup(self.upHintEnt,     self._showUpHint,       false)
        self:_SetCanvasGroup(self.forwardHintEnt, self._showForwardHint, false)
        self:_SetCanvasGroup(self.downHintEnt,   self._showDownHint,     true)

        DreamSpaceStates.IsShowJumpUI = true
        self.catJumpCurve:ShowJump( self.catHeadTF.position, self._downHintWorldPos )

    else    
        DreamSpaceStates.IsShowJumpUI = false
        self.catJumpCurve:Hide( self.catHeadTF.position )


    end
end


function JumpHint:_SetCanvasGroup(hintEnv_, isChoosed_, isFst_)
    self:_SetCanvasGroupParameters(
        hintEnv_,
        isFst_,
        isFst_ and 1 or (isChoosed_ and _secondAlpha or 0)
    )
end



function JumpHint:_SetCanvasGroupParameters(hintEnv_, isInteractable_, alpha_)

    local canvasGroup = hintEnv_.canvasGroup

    if canvasGroup.alpha ~= alpha_ then 
        if alpha_ > 0.5 then 
            hintEnv_:PlayShow()
        else 
            hintEnv_:PlayHide()
        end 
    end 

    canvasGroup.interactable = isInteractable_
    canvasGroup.alpha = alpha_
end



return JumpHint

